INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(400, 'articles of association', '/ˈɑːrtɪkəlz əv əˌsoʊsiˈeɪʃən/', 'noun', '{"zh-TW":["公司章程"],"en":["a document governing how a company is internally managed"]}', NULL, 'amend articles of association / file articles of association', '[{"en":"The articles of association define voting rights and board powers.","zh-TW":"公司章程規定了投票權和董事會權力。"},{"en":"Changes to the articles of association require shareholder approval.","zh-TW":"對公司章程的修改需要股東批准。"}]', NULL, NULL, 5, 400, NULL),
(401, 'articulate', '/ɑːrˈtɪkjʊleɪt/', 'verb', '{"zh-TW":["清楚地表達；闡述"],"en":["to express clearly and effectively"]}', NULL, 'articulate a vision / articulate concerns', '[{"en":"She articulated the company''s strategy clearly to investors.","zh-TW":"她向投資者清楚地闡述了公司的策略。"},{"en":"The manager articulated concerns about the project timeline.","zh-TW":"經理清楚地表達了對項目時間表的顧慮。"}]', '{"adjective":"articulate","adverb":"articulately"}', NULL, 4, 401, 955),
(402, 'artifact', '/ˈɑːrtɪfækt/', 'noun', '{"zh-TW":["文物；人工製品"],"en":["an object made by a human, especially one of historical interest"]}', '{"root":{"text":"arti","meaning":"skill (技藝)"},"suffix":{"text":"fact","meaning":"made (製造)"},"logic":"用技藝製造的東西，即「工藝品」。"}', 'ancient artifact / cultural artifact', '[{"en":"The museum displays artifacts from ancient Egypt.","zh-TW":"博物館展示古埃及文物。"},{"en":"Archaeologists discovered several artifacts at the site.","zh-TW":"考古學家在遺址發現了數件文物。"}]', NULL, NULL, 3, 402, NULL),
(403, 'artificial', '/ˌɑːrtɪˈfɪʃəl/', 'adjective', '{"zh-TW":["人工的；人造的"],"en":["made by people; not natural","made by humans rather than occurring naturally"]}', '{"root":{"text":"arti","meaning":"skill/craft (技藝)"},"suffix":{"text":"-ficial","meaning":"making (製造)"},"logic":"用技藝製造的，即「人工的」。"}', 'artificial intelligence / artificial flavor', '[{"en":"Artificial intelligence is changing the world.","zh-TW":"人工智慧正在改變世界。"},{"en":"The flowers are artificial.","zh-TW":"這些花是人造的。"},{"en":"The lake is artificial, not natural.","zh-TW":"這個湖是人工的，不是天然的。"},{"en":"Artificial intelligence is transforming many industries.","zh-TW":"人工智慧正在改變許多產業。"}]', '{"adverb":"artificially"}', NULL, 4, 403, NULL),
(404, 'artificial intelligence', '/ˌɑːrtɪˈfɪʃəl ɪnˈtelɪdʒəns/', 'noun', '{"zh-TW":["人工智慧"],"en":["simulation of human intelligence processes by computer systems"]}', NULL, 'AI-powered / artificial intelligence tools / leverage AI / AI strategy', '[{"en":"Artificial intelligence is transforming how businesses make decisions.","zh-TW":"人工智慧正在改變企業的決策方式。"},{"en":"The company deployed AI to improve customer service response times.","zh-TW":"公司部署人工智慧以改善客戶服務響應時間。"}]', '{"abbreviation":"AI","adjective":"AI-driven"}', NULL, 5, 404, NULL),
(405, 'artisan', '/''ɑːrtɪzən/', 'noun', '{"zh-TW":["工匠；手工藝師"],"en":["a person who makes high-quality products by hand; also used as an adjective for handcrafted goods"]}', NULL, 'artisan bread / artisan cheese / artisan market', '[{"en":"The artisan bakery made all its breads by hand using traditional methods.","zh-TW":"這家工匠麵包店使用傳統方法全部手工製作麵包。"},{"en":"Artisan cheeses from local farms are featured on the restaurant''s menu.","zh-TW":"來自當地農場的工匠起司是餐廳菜單上的特色。"}]', '{"adjective":"artisanal"}', NULL, 3, 405, NULL),
(406, 'ask', '/ɑːsk/', 'verb', '{"zh-TW":["詢問；要求；邀請"],"en":["to say something to get an answer; to request"]}', NULL, 'ask for / ask sb to do sth / ask about', '[{"en":"Can I ask you a question?","zh-TW":"我可以問你一個問題嗎？"},{"en":"She asked for a raise.","zh-TW":"她要求加薪。"}]', NULL, NULL, 1, 406, NULL),
(407, 'ask price', '/ɑːsk praɪs/', 'noun', '{"zh-TW":["賣出價；要價"],"en":["the price a seller is willing to accept for a security or asset"]}', NULL, 'quote an ask price / bid-ask spread', '[{"en":"The ask price for the shares was $10.50 per unit.","zh-TW":"股份的賣出價為每單位10.50元。"},{"en":"The difference between bid and ask price is called the spread.","zh-TW":"買入價和賣出價之間的差額稱為差價。"}]', '{"opposite":"bid price","synonym":"offer price"}', NULL, 3, 407, NULL),
(408, 'asking price', '/''ɑːskɪŋ praɪs/', 'noun', '{"zh-TW":["開價；要求售價"],"en":["the price at which a seller offers a property for sale"]}', NULL, 'above the asking price / below the asking price / negotiate the asking price', '[{"en":"The apartment sold at the full asking price within the first week on the market.","zh-TW":"公寓在上市第一週內以全額開價售出。"},{"en":"Buyers often start their negotiations below the asking price.","zh-TW":"買家通常在低於開價的情況下開始談判。"}]', NULL, NULL, 4, 408, NULL),
(409, 'aspect', '/ˈæspekt/', 'noun', '{"zh-TW":["方面；層面"],"en":["a particular part or feature of something"]}', '{"prefix":{"text":"a-","meaning":"to (朝向)"},"root":{"text":"spect","meaning":"look (看)"},"logic":"從某個方向看過去的面向，即「方面」。"}', 'important aspect / every aspect / key aspect', '[{"en":"We need to consider every aspect of the problem.","zh-TW":"我們需要考慮問題的每個方面。"},{"en":"Safety is the most important aspect of the job.","zh-TW":"安全是這份工作最重要的面向。"}]', NULL, NULL, 2, 409, NULL),
(410, 'assemble', '/əˈsembl/', 'verb', '{"zh-TW":["組裝；集合"],"en":["to fit together the parts of","to come together in one place","to put together the parts of"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"semble","meaning":"together (一起)"},"logic":"朝向一起，即「組裝、集合」。"}', 'assemble a team/product/parts; assemble a team / assemble furniture', '[{"en":"Workers assemble the components on the factory floor.","zh-TW":"工人在工廠車間組裝零件。"},{"en":"The committee assembled to discuss the proposal.","zh-TW":"委員會集合討論該提案。"},{"en":"Workers assemble the products on the factory floor.","zh-TW":"工人在工廠樓層組裝產品。"},{"en":"The team assembled in the conference room.","zh-TW":"團隊在會議室集合。"}]', '{"noun":"assembly"}', NULL, 3, 410, 648),
(411, 'assert', '/əˈsɜːrt/', 'verb', '{"zh-TW":["斷言；主張"],"en":["to state something clearly and firmly"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sert","meaning":"join/bind (結合)"},"logic":"朝向牢固結合的聲明，即「斷言」。"}', 'assert rights/authority/claims', '[{"en":"The company asserted its right to the patent.","zh-TW":"公司主張其專利權。"},{"en":"She asserted that the data was accurate.","zh-TW":"她斷言資料是準確的。"}]', '{"noun":"assertion","adjective":"assertive"}', NULL, 2, 411, NULL),
(412, 'assertion', '/əˈsɜːrʃən/', 'noun', '{"zh-TW":["主張；斷言"],"en":["a confident and forceful statement"]}', NULL, 'make an assertion / bold assertion / unsupported assertion', '[{"en":"His assertion was not backed by any data.","zh-TW":"他的主張沒有任何數據支持。"},{"en":"The paper makes several assertions that require empirical verification.","zh-TW":"該論文提出了幾個需要實證驗證的主張。"}]', '{"verb":"assert","adjective":"assertive"}', NULL, 3, 412, NULL),
(413, 'assertive', '/''əˈsɜːrtɪv/', 'adjective', '{"zh-TW":["自信的；有主見的"],"en":["having or showing a confident and forceful personality; able to express opinions firmly"]}', NULL, 'assertive communication / be assertive / become more assertive', '[{"en":"Being assertive means expressing your needs clearly without being aggressive.","zh-TW":"自信是指清楚地表達你的需求而不具有攻擊性。"},{"en":"Assertive employees are more likely to share valuable ideas and stand up for their rights.","zh-TW":"自信的員工更有可能分享有價值的想法並維護自己的權益。"}]', '{"noun":"assertiveness","adverb":"assertively"}', NULL, 3, 413, NULL),
(414, 'assertiveness training', '/''əˈsɜːrtɪvnəs ˌtreɪnɪŋ/', 'noun', '{"zh-TW":["自信表達培訓；自我主張訓練"],"en":["training that helps people communicate their needs and boundaries clearly and confidently"]}', NULL, 'attend assertiveness training / benefit from assertiveness training / need assertiveness training', '[{"en":"Assertiveness training helped her speak up in meetings and share her ideas more confidently.","zh-TW":"自信表達培訓幫助她在會議中發言，更自信地分享她的想法。"},{"en":"Many professionals benefit from assertiveness training to improve workplace communication.","zh-TW":"許多專業人士受益於自信表達培訓，以改善工作場所的溝通。"}]', NULL, NULL, 5, 414, NULL),
(415, 'assess', '/əˈses/', 'verb', '{"zh-TW":["評估；估算"],"en":["to evaluate or estimate the nature or quality of"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sess","meaning":"sit (坐)"},"logic":"坐下來朝向審視，即「評估」。"}', 'assess risk/damage/performance', '[{"en":"We need to assess the potential risks before investing.","zh-TW":"投資前我們需要評估潛在風險。"},{"en":"The damage was assessed at $2 million.","zh-TW":"損失估計為200萬美元。"}]', '{"noun":"assessment"}', NULL, 2, 415, NULL),
(416, 'assess risk', '/əˈses rɪsk/', 'verb', '{"zh-TW":["評估風險"],"en":["to identify, analyze, and evaluate potential risks before taking action"]}', NULL, 'assess risk before investing / regularly assess risk', '[{"en":"Managers must assess risk before approving capital expenditure.","zh-TW":"管理者在批准資本支出前必須評估風險。"},{"en":"The team assessed risk using a probability-impact matrix.","zh-TW":"團隊使用概率-影響矩陣評估了風險。"}]', '{"noun":"risk assessment","noun2":"assessor"}', NULL, 4, 416, NULL),
(417, 'assessed value', '/əˈsest ˈvæljuː/', 'noun', '{"zh-TW":["評定價值；課稅估值"],"en":["the value assigned to a property for tax purposes"]}', NULL, 'assessed value of the property / calculate assessed value', '[{"en":"Property taxes are based on the assessed value of the property.","zh-TW":"房產稅基於物業的評定價值計算。"},{"en":"The assessed value was lower than the market value.","zh-TW":"評定價值低於市場價值。"}]', NULL, NULL, 5, 417, NULL),
(418, 'assessment', '/əˈsesmənt/', 'noun', '{"zh-TW":["評估；鑑定"],"en":["the process of evaluating performance, risk, or capability"]}', NULL, 'risk assessment / needs assessment / performance assessment / conduct an assessment', '[{"en":"A comprehensive risk assessment was conducted before the project launch.","zh-TW":"在項目啟動前進行了全面的風險評估。"},{"en":"The assessment revealed gaps in the team''s technical skills.","zh-TW":"評估揭示了團隊技術技能方面的差距。"}]', '{"verb":"assess","noun":"assessor"}', NULL, 4, 418, 268),
(419, 'asset', '/ˈæset/', 'noun', '{"zh-TW":["資產"],"en":["any resource owned by a company with economic value"]}', NULL, 'current asset / fixed asset / intangible asset / asset management / asset valuation', '[{"en":"The company''s most valuable asset is its brand reputation.","zh-TW":"公司最有價值的資產是其品牌聲譽。"},{"en":"Total assets on the balance sheet exceeded $1 billion.","zh-TW":"資產負債表上的總資產超過10億美元。"}]', '{"plural":"assets","adjective":"asset-rich"}', NULL, 2, 419, 269),
(420, 'asset allocation', '/ˈæset ˌæləˈkeɪʃən/', 'noun', '{"zh-TW":["資產配置"],"en":["distributing investments among different asset classes"]}', NULL, 'strategic asset allocation / dynamic asset allocation', '[{"en":"Asset allocation determines the risk-return profile of a portfolio.","zh-TW":"資產配置決定了投資組合的風險回報特徵。"},{"en":"She adjusted her asset allocation as she neared retirement.","zh-TW":"她在接近退休時調整了資產配置。"}]', '{"verb":"allocate assets"}', NULL, 5, 420, NULL),
(421, 'asset class', '/ˈæset klɑːs/', 'noun', '{"zh-TW":["資產類別"],"en":["a category of investments with similar characteristics and market behaviors"]}', NULL, 'diversify across asset classes / asset class allocation', '[{"en":"Bonds and equities are distinct asset classes with different risk profiles.","zh-TW":"債券和股票是具有不同風險特徵的不同資產類別。"},{"en":"Portfolio managers allocate capital across multiple asset classes.","zh-TW":"投資組合管理人在多種資產類別中分配資本。"}]', NULL, NULL, 4, 421, NULL),
(422, 'asset disposal', '/ˈæset dɪˈspoʊzəl/', 'noun', '{"zh-TW":["資產處置"],"en":["the process of selling or writing off an asset that is no longer needed"]}', NULL, 'manage asset disposal / asset disposal proceeds', '[{"en":"The asset disposal generated $500000 for reinvestment.","zh-TW":"資產處置產生了50萬元用於再投資。"},{"en":"Proceeds from asset disposal were used to reduce company debt.","zh-TW":"資產處置所得用於減少公司債務。"}]', NULL, NULL, 5, 422, NULL),
(423, 'asset impairment', '/ˈæset ɪmˈpeərmənt/', 'noun', '{"zh-TW":["資產減值"],"en":["a reduction in the carrying value of an asset due to a decline in its recoverable amount"]}', NULL, 'record asset impairment / asset impairment test', '[{"en":"An asset impairment charge was recognized after the plant closure.","zh-TW":"工廠關閉後確認了資產減值費用。"},{"en":"Annual asset impairment tests are required by international accounting standards.","zh-TW":"國際會計準則要求進行年度資產減值測試。"}]', NULL, NULL, 5, 423, NULL),
(424, 'asset management', '/ˈæsɛt ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["資產管理"],"en":["the professional management of financial and physical assets"]}', NULL, 'investment asset management / asset management company', '[{"en":"She works at an asset management company specializing in equity.","zh-TW":"她在一家專門從事股票的資產管理公司工作。"},{"en":"Asset management ensures that resources are used efficiently.","zh-TW":"資產管理確保資源得到有效使用。"}]', NULL, NULL, 5, 424, NULL),
(425, 'asset management company', '/ˈæset ˈmænɪdʒmənt ˈkʌmpəni/', 'noun', '{"zh-TW":["資產管理公司"],"en":["a firm that manages investments and financial portfolios on behalf of clients"]}', NULL, 'hire an asset management company / asset management company services', '[{"en":"The pension fund engaged an asset management company to grow returns.","zh-TW":"養老基金聘請了一家資產管理公司來增加回報。"},{"en":"Asset management companies charge fees based on assets under management.","zh-TW":"資產管理公司根據管理的資產規模收取費用。"}]', NULL, NULL, 5, 425, NULL),
(426, 'asset register', '/ˈæset ˈredʒɪstər/', 'noun', '{"zh-TW":["資產登記冊"],"en":["a record listing all assets owned by an organization with their details"]}', NULL, 'maintain an asset register / asset register update', '[{"en":"The asset register must be updated whenever assets are purchased or disposed of.","zh-TW":"每次購買或處置資產時，必須更新資產登記冊。"},{"en":"An accurate asset register supports insurance coverage and depreciation.","zh-TW":"準確的資產登記冊支持保險保障和折舊計算。"}]', NULL, NULL, 5, 426, NULL),
(427, 'asset turnover', '/ˈæset ˈtɜːrnoʊvər/', 'noun', '{"zh-TW":["資產周轉率"],"en":["a financial ratio measuring how efficiently a company uses its assets to generate revenue"]}', NULL, 'calculate asset turnover / improve asset turnover', '[{"en":"A high asset turnover ratio indicates efficient use of company assets.","zh-TW":"高資產周轉率表明公司資產使用效率高。"},{"en":"The company improved asset turnover by disposing of underperforming assets.","zh-TW":"公司通過處置業績不佳的資產改善了資產周轉率。"}]', NULL, NULL, 5, 427, NULL),
(428, 'asset valuation', '/ˈæset ˌvæljuˈeɪʃən/', 'noun', '{"zh-TW":["資產評估"],"en":["the process of determining the current worth of a company''s assets"]}', NULL, 'conduct asset valuation / asset valuation report', '[{"en":"An independent asset valuation was required for the merger.","zh-TW":"合併需要獨立的資產評估。"},{"en":"Asset valuation methods include market value and replacement cost.","zh-TW":"資產評估方法包括市場價值和重置成本。"}]', NULL, NULL, 5, 428, NULL),
(429, 'asset-backed securities', '/ˈæset bækt sɪˈkjʊərɪtiz/', 'noun', '{"zh-TW":["資產抵押證券"],"en":["financial instruments backed by a pool of underlying assets"]}', NULL, 'issue asset-backed securities / invest in asset-backed securities', '[{"en":"Mortgage-backed securities are a type of asset-backed securities.","zh-TW":"抵押支持證券是資產抵押證券的一種。"},{"en":"Asset-backed securities played a major role in the financial crisis.","zh-TW":"資產抵押證券在金融危機中扮演了重要角色。"}]', '{"abbreviation":"ABS"}', NULL, 5, 429, NULL),
(430, 'asset-backed security', '/ˈæset bækt sɪˈkjʊərɪti/', 'noun', '{"zh-TW":["資產擔保證券"],"en":["a financial instrument backed by a pool of assets such as loans or receivables"]}', NULL, 'issue asset-backed securities / asset-backed security risk', '[{"en":"The bank securitized its auto loan portfolio into asset-backed securities.","zh-TW":"銀行將其汽車貸款組合證券化為資產擔保證券。"},{"en":"Asset-backed securities allow banks to free up capital for new lending.","zh-TW":"資產擔保證券使銀行能夠釋放資本用於新貸款。"}]', '{"abbreviation":"ABS"}', NULL, 5, 430, NULL),
(431, 'asset-light', '/ˈæset laɪt/', 'adjective', '{"zh-TW":["輕資產的"],"en":["describing a business model that relies on few physical assets"]}', NULL, 'asset-light model / asset-light strategy / asset-light company', '[{"en":"Franchise businesses are typically asset-light.","zh-TW":"特許經營企業通常是輕資產的。"},{"en":"The firm transitioned to an asset-light model by outsourcing logistics.","zh-TW":"公司通過將物流外包轉型為輕資產模式。"}]', NULL, NULL, 4, 431, NULL),
(432, 'assign', '/əˈsaɪn/', 'verb', '{"zh-TW":["分配；指派"],"en":["to give someone a particular job or task"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sign","meaning":"mark (標記)"},"logic":"朝向標記某人做某事，即「指派」。"}', 'assign a task/role/responsibility', '[{"en":"The manager assigned the task to the new employee.","zh-TW":"經理將任務分配給新員工。"},{"en":"Each team member was assigned a specific role.","zh-TW":"每位團隊成員被指派了特定角色。"}]', '{"noun":"assignment"}', NULL, 2, 432, 270),
(433, 'assign responsibility', '/əˈsaɪn rɪˌspɒnsɪˈbɪlɪti/', 'verb', '{"zh-TW":["指派責任"],"en":["to designate someone as being accountable for a task or outcome"]}', NULL, 'assign clear responsibility / assign responsibility for each task', '[{"en":"Responsibility for data security was assigned to the IT director.","zh-TW":"資料安全的責任被指派給了IT總監。"},{"en":"Each project milestone had an assigned responsibility owner.","zh-TW":"每個項目里程碑都有指派的責任人。"}]', NULL, NULL, 5, 433, NULL),
(434, 'assigned', 'əˈsaɪnd', 'adjective', '{"zh-TW":["指定的；分配的","負責的"],"en":["given a specific task","allocated"]}', NULL, 'assigned tasks/assigned responsibilities', '[{"en":"Complete your assigned tasks on time.","zh-TW":"按時完成您的指定任務。"}]', '{"verb":"assign","noun":"assignment"}', NULL, 3, 434, NULL),
(435, 'assignment', '/əˈsaɪnmənt/', 'noun', '{"zh-TW":["作業；任務"],"en":["a task given as part of a job or studies"]}', NULL, 'homework assignment / complete an assignment', '[{"en":"The assignment is due on Friday.","zh-TW":"作業週五到期。"},{"en":"She completed all her assignments on time.","zh-TW":"她按時完成了所有作業。"}]', '{"verb":"assign"}', NULL, 4, 435, 508),
(436, 'assignment of contract', '/əˈsaɪnmənt əv ˈkɒntrækt/', 'noun', '{"zh-TW":["合約轉讓"],"en":["the transfer of contractual rights or obligations from one party to another"]}', NULL, 'permit assignment of contract / assignment of contract clause', '[{"en":"An assignment of contract clause requires prior written consent.","zh-TW":"合約轉讓條款需要事先書面同意。"},{"en":"The assignment of contract was approved by all parties involved.","zh-TW":"所有相關各方批准了合約轉讓。"}]', NULL, NULL, 5, 436, NULL),
(437, 'assimilate', '/''əˌsɪmɪˌleɪt/', 'verb', '{"zh-TW":["同化；吸收；消化"],"en":["to take in and understand fully; to absorb into a group or culture"]}', NULL, 'assimilate information / assimilate into society / assimilate quickly', '[{"en":"It took her several months to assimilate all the new information from the training.","zh-TW":"她花了幾個月的時間吸收培訓中的所有新信息。"},{"en":"Immigrants often face challenges as they try to assimilate into a new culture.","zh-TW":"移民在嘗試融入新文化時往往面臨挑戰。"}]', '{"noun":"assimilation","adjective":"assimilated"}', NULL, 4, 437, NULL),
(438, 'assimilation', '/əˌsɪmɪˈleɪʃən/', 'noun', '{"zh-TW":["同化；融合"],"en":["the process by which a minority group adopts the culture of the dominant group"]}', NULL, 'cultural assimilation / forced assimilation / assimilation of immigrants', '[{"en":"Critics argue that forced assimilation erases important cultural heritage.","zh-TW":"批評者認為強迫同化抹去了重要的文化遺產。"},{"en":"Immigrants face pressure to assimilation into the dominant culture.","zh-TW":"移民面臨著融入主流文化的壓力。"}]', '{"verb":"assimilate","adjective":"assimilated"}', NULL, 4, 438, NULL),
(439, 'assist', '/əˈsɪst/', 'verb', '{"zh-TW":["協助；幫助"],"en":["to help or give support to someone"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sist","meaning":"stand (站)"},"logic":"站在旁邊支持，即「協助」。"}', 'assist with / assist in doing', '[{"en":"Our team will assist you with the transition.","zh-TW":"我們的團隊將協助您完成過渡。"},{"en":"Can I assist you in finding what you need?","zh-TW":"我能幫您找到您需要的東西嗎？"}]', '{"noun":"assistance","noun2":"assistant"}', NULL, 2, 439, 73),
(440, 'assistance', 'əˈsɪstəns', 'noun', '{"zh-TW":["協助；幫助","支援"],"en":["help or support given","aid provided"]}', NULL, 'technical assistance/request assistance', '[{"en":"Please call us if you need any assistance.","zh-TW":"如果您需要任何幫助，請致電。"}]', '{"verb":"assist","adjective":"assistive"}', NULL, 4, 440, NULL),
(441, 'associate', '/əˈsəʊsieɪt/', 'verb', '{"zh-TW":["聯想；關聯","交往"],"en":["to connect in one''s mind","to spend time with someone"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"soci","meaning":"companion (夥伴)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使成為夥伴，即「關聯」。"}', 'associate with / be associated with', '[{"en":"Customers associate the brand with quality.","zh-TW":"顧客將該品牌與品質聯繫在一起。"},{"en":"High stress is associated with health problems.","zh-TW":"高壓力與健康問題有關。"}]', '{"noun":"association"}', NULL, 3, 441, NULL),
(442, 'associated costs', '/əˈsoʊsiˌeɪtɪd kɒsts/', 'noun', '{"zh-TW":["相關成本；附帶費用"],"en":["additional costs that arise in connection with a primary activity or purchase"]}', NULL, 'identify associated costs / minimize associated costs', '[{"en":"The project''s associated costs exceeded the initial estimate by 20%.","zh-TW":"項目的相關成本超出了初始估計20%。"},{"en":"All associated costs were disclosed in the financial summary.","zh-TW":"所有相關成本均在財務摘要中披露了。"}]', NULL, NULL, 5, 442, NULL),
(443, 'assume', '/əˈsjuːm/', 'verb', '{"zh-TW":["假設；承擔"],"en":["to suppose to be true without proof","to take on responsibility"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sume","meaning":"take (拿取)"},"logic":"朝向拿取（未證實的），即「假設」。"}', 'assume responsibility/role/risk', '[{"en":"Let''s assume the project will take six months.","zh-TW":"我們假設這個專案需要六個月。"},{"en":"She assumed the role of department head.","zh-TW":"她承擔了部門主管的角色。"}]', '{"noun":"assumption"}', NULL, 2, 443, NULL),
(444, 'assumption', '/əˈsʌmpʃən/', 'noun', '{"zh-TW":["假設；前提"],"en":["a condition believed to be true without verification, used in planning"]}', NULL, 'project assumption / document assumptions / challenge an assumption', '[{"en":"All project assumptions were recorded in the project charter.","zh-TW":"所有項目假設都記錄在項目章程中。"},{"en":"Failing to validate assumptions early caused the project to fail.","zh-TW":"未能早期驗證假設導致項目失敗。"}]', '{"plural":"assumptions","verb":"assume"}', NULL, 4, 444, 509),
(445, 'assure', '/əˈʃʊər/', 'verb', '{"zh-TW":["保證；使確信","向…保證；確保"],"en":["to tell someone confidently to remove doubt","to tell someone confidently that something is true"]}', '{"prefix":{"text":"as-","meaning":"toward (朝向)"},"root":{"text":"sure","meaning":"sure (確定)"},"logic":"朝向使人確定，即「保證」。"}', 'assure sb that / rest assured; assure someone that / rest assured / I assure you', '[{"en":"I assure you that the issue will be resolved promptly.","zh-TW":"我向您保證問題將盡快解決。"},{"en":"Rest assured, your data is secure.","zh-TW":"請放心，您的資料是安全的。"},{"en":"I assure you the problem will be fixed.","zh-TW":"我向你保證問題會被解決。"},{"en":"Rest assured, your data is safe.","zh-TW":"請放心，你的資料是安全的。"}]', '{"noun":"assurance","adjective":"assured"}', NULL, 2, 445, 728),
(446, 'astounding', '/''əˈstaʊndɪŋ/', 'adjective', '{"zh-TW":["令人驚嘆的；驚人的"],"en":["surprisingly impressive or notable"]}', NULL, 'astounding results / astounding growth / astounding achievement', '[{"en":"The startup''s astounding growth attracted investment from all over the world.","zh-TW":"這家新創公司令人驚嘆的增長吸引了來自世界各地的投資。"},{"en":"Her astounding ability to retain complex information set her apart from other candidates.","zh-TW":"她令人驚嘆的記憶複雜信息的能力使她在其他候選人中脫穎而出。"}]', '{"adverb":"astoundingly","verb":"astound"}', NULL, 4, 446, NULL),
(447, 'astute', '/''əˈstjuːt/', 'adjective', '{"zh-TW":["敏銳的；精明的"],"en":["having an ability to accurately assess situations or people and turn this to one''s advantage"]}', NULL, 'astute businessperson / astute observation / astute investor', '[{"en":"An astute investor recognizes opportunities that others overlook.","zh-TW":"一位精明的投資者能夠識別他人忽視的機會。"},{"en":"Her astute observations during the negotiation helped secure a favorable deal.","zh-TW":"她在談判中的敏銳觀察幫助達成了有利的交易。"}]', '{"adverb":"astutely","noun":"astuteness"}', NULL, 2, 447, NULL),
(448, 'astute observer', '/''əˌstjuːt əbˌzɜːrvər/', 'noun', '{"zh-TW":["敏銳的觀察者"],"en":["someone who notices things and forms accurate judgments quickly and cleverly"]}', NULL, 'act as an astute observer / be an astute observer of / known as an astute observer', '[{"en":"As an astute observer of market trends, she often predicted shifts before others noticed.","zh-TW":"作為市場趨勢的敏銳觀察者，她往往在其他人注意到之前就預測到了變化。"},{"en":"An astute observer can read the room and adjust communication style accordingly.","zh-TW":"敏銳的觀察者能夠解讀場景，並相應地調整溝通方式。"}]', '{"adjective":"astute"}', NULL, 5, 448, NULL),
(449, 'asynchronous', '/eɪˈsɪŋkrənəs/', 'adjective', '{"zh-TW":["非同步的"],"en":["not occurring at the same time; allowing operations to proceed independently"]}', NULL, 'asynchronous processing / asynchronous communication / asynchronous task', '[{"en":"Asynchronous processing improves the responsiveness of web applications.","zh-TW":"非同步處理提高了網路應用程式的回應能力。"},{"en":"The system uses asynchronous message queues to handle high traffic volumes.","zh-TW":"系統使用非同步訊息佇列來處理高流量。"}]', '{"adverb":"asynchronously","noun":"asynchrony"}', NULL, 4, 449, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(450, 'at par', '/æt pɑːr/', 'phrase', '{"zh-TW":["按面值；按平價"],"en":["at the nominal or face value of a security or financial instrument"]}', NULL, 'issued at par / redeemed at par / trade at par', '[{"en":"The bonds were issued at par and mature in five years.","zh-TW":"債券按面值發行，五年後到期。"},{"en":"Shares trading at par indicate market confidence in book value.","zh-TW":"按面值交易的股份表明市場對帳面價值有信心。"}]', NULL, NULL, 2, 450, NULL),
(451, 'at-will employment', '/æt wɪl ɪmˈplɔɪmənt/', 'noun', '{"zh-TW":["隨意雇用"],"en":["an employment arrangement where either party can terminate at any time without cause"]}', NULL, 'at-will employment contract / at-will employment policy', '[{"en":"At-will employment means the employer can terminate without advance notice.","zh-TW":"隨意雇用意味著雇主可以在不提前通知的情況下終止雇用。"},{"en":"Some states restrict at-will employment through protective legislation.","zh-TW":"一些州通過保護性立法限制了隨意雇用。"}]', NULL, NULL, 5, 451, NULL),
(452, 'athlete', '/ˈæθliːt/', 'noun', '{"zh-TW":["運動員"],"en":["a person who is good at sports"]}', NULL, 'professional athlete / athlete''s performance', '[{"en":"She is a talented athlete.","zh-TW":"她是一位有天賦的運動員。"},{"en":"The athlete broke the world record.","zh-TW":"那位運動員打破了世界紀錄。"}]', '{"adjective":"athletic","noun2":"athletics"}', NULL, 3, 452, NULL),
(453, 'athletic', '/''æθˈletɪk/', 'adjective', '{"zh-TW":["運動的；體格健壯的"],"en":["physically strong, fit, and active; relating to athletes or athletics"]}', NULL, 'athletic build / athletic performance / athletic ability', '[{"en":"Her athletic build was ideal for competitive swimming.","zh-TW":"她健壯的體格非常適合競技游泳。"},{"en":"The school offers a wide range of athletic programs for students of all ages.","zh-TW":"學校為各年齡層的學生提供廣泛的運動計畫。"}]', '{"noun":"athlete","noun2":"athletics"}', NULL, 3, 453, NULL),
(454, 'athletic performance', '/''æθˌletɪk pəˌfɔːrməns/', 'noun', '{"zh-TW":["運動表現；競技表現"],"en":["the level of ability or achievement in sport or physical activity"]}', NULL, 'improve athletic performance / assess athletic performance / optimize athletic performance', '[{"en":"Adequate sleep is essential for maintaining and improving athletic performance.","zh-TW":"充足的睡眠對維持和改善運動表現至關重要。"},{"en":"The coach monitored each player''s athletic performance throughout the season.","zh-TW":"教練在整個賽季監測每位球員的運動表現。"}]', '{"adjective":"athletic"}', NULL, 5, 454, NULL),
(455, 'athletic scholarship', '/''æθˈletɪk ˌskɒlərʃɪp/', 'noun', '{"zh-TW":["體育獎學金"],"en":["financial aid awarded to a student primarily on the basis of athletic ability"]}', NULL, 'receive an athletic scholarship / earn an athletic scholarship / full athletic scholarship', '[{"en":"She received a full athletic scholarship to study and play tennis at the university.","zh-TW":"她獲得了在大學學習和打網球的全額體育獎學金。"},{"en":"Athletic scholarships help talented young athletes afford higher education.","zh-TW":"體育獎學金幫助有才華的年輕運動員負擔高等教育費用。"}]', NULL, NULL, 5, 455, NULL),
(456, 'athletic training', '/''æθˌletɪk ˌtreɪnɪŋ/', 'noun', '{"zh-TW":["運動訓練；競技訓練"],"en":["systematic practice aimed at improving performance in a sport or physical activity"]}', NULL, 'undergo athletic training / athletic training program / benefit of athletic training', '[{"en":"She underwent intensive athletic training for six months before the national competition.","zh-TW":"她在全國比賽前進行了六個月的密集運動訓練。"},{"en":"Athletic training combines physical conditioning, technique development, and mental preparation.","zh-TW":"運動訓練結合了體能調整、技術發展和心理準備。"}]', '{"adjective":"athletic"}', NULL, 5, 456, NULL),
(457, 'ATM', '/eɪ tiː ɛm/', 'noun', '{"zh-TW":["自動提款機"],"en":["a machine that allows bank customers to withdraw cash"]}', NULL, 'use an ATM / ATM withdrawal', '[{"en":"She withdrew cash from the ATM near the hotel.","zh-TW":"她在飯店附近的自動提款機提取了現金。"},{"en":"ATM fees apply when using machines outside your network.","zh-TW":"使用網絡外的機器時需支付自動提款機手續費。"}]', NULL, NULL, 1, 457, NULL),
(458, 'atmosphere', '/ˈætməsfɪr/', 'noun', '{"zh-TW":["大氣層；氣氛"],"en":["the layer of gases around the earth","the mood or feeling of a place"]}', '{"root":{"text":"atmos","meaning":"vapor (蒸氣)"},"suffix":{"text":"sphere","meaning":"ball (球)"},"logic":"蒸氣包圍的球體，即「大氣層」。"}', 'earth''s atmosphere / friendly atmosphere', '[{"en":"The atmosphere at the party was lively.","zh-TW":"派對的氣氛很活絡。"},{"en":"Pollution is damaging the atmosphere.","zh-TW":"汙染正在破壞大氣層。"}]', '{"adjective":"atmospheric"}', NULL, 4, 458, NULL),
(459, 'atrium', '/ˈeɪtriəm/', 'noun', '{"zh-TW":["中庭大廳"],"en":["a large open space inside a building"]}', NULL, 'hotel atrium / glass atrium', '[{"en":"The hotel has a stunning glass atrium with natural light.","zh-TW":"飯店有令人驚嘆的玻璃中庭，採光自然。"},{"en":"Guests can relax in the central atrium.","zh-TW":"賓客可以在中央中庭休息。"}]', NULL, NULL, 2, 459, NULL),
(460, 'attach', '/əˈtætʃ/', 'verb', '{"zh-TW":["附上；連接"],"en":["to fasten or join one thing to another"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tach","meaning":"stake/fasten (釘住)"},"logic":"朝向釘住，即「附上」。"}', 'attach a file/document/label', '[{"en":"Please find the report attached to this email.","zh-TW":"請查看附在此電子郵件中的報告。"},{"en":"Attach the receipt to your expense claim.","zh-TW":"請將收據附在您的報銷申請上。"}]', '{"noun":"attachment"}', NULL, 2, 460, NULL),
(461, 'attached', '/əˈtætʃt/', 'adjective', '{"zh-TW":["附件的；附上的"],"en":["joined or fastened to something; included with a message"]}', NULL, 'as attached / please find attached', '[{"en":"Please find the report attached to this email.","zh-TW":"請查看此電子郵件的附件報告。"},{"en":"The attached document outlines the terms of the agreement.","zh-TW":"附件文件概述了協議條款。"}]', '{"verb":"attach","noun":"attachment"}', NULL, 3, 461, NULL),
(462, 'attachment', '/əˈtætʃmənt/', 'noun', '{"zh-TW":["附件；附加物"],"en":["a file sent along with an email or document"]}', NULL, 'email attachment / download the attachment', '[{"en":"Please open the attachment for the full report.","zh-TW":"請打開附件查看完整報告。"},{"en":"The attachment contains all the required forms.","zh-TW":"附件包含所有所需的表格。"}]', '{"verb":"attach","adjective":"attached"}', NULL, 4, 462, 510),
(463, 'attack', '/əˈtæk/', 'noun', '{"zh-TW":["攻擊；發作"],"en":["an act of violence against someone"]}', NULL, 'heart attack / under attack', '[{"en":"The city was under attack.","zh-TW":"城市遭受了攻擊。"},{"en":"He suffered a heart attack.","zh-TW":"他心臟病發作了。"}]', '{"verb":"attack","noun2":"attacker"}', NULL, 2, 463, NULL),
(464, 'attain', '/əˈteɪn/', 'verb', '{"zh-TW":["達到；獲得"],"en":["to succeed in achieving something after effort"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tain","meaning":"hold (持有)"},"logic":"朝向持有，即「達到」。"}', 'attain a goal/level/standard', '[{"en":"Few companies attain such high customer satisfaction ratings.","zh-TW":"很少有公司達到如此高的客戶滿意度。"},{"en":"He attained the rank of senior vice president.","zh-TW":"他達到了資深副總裁的職位。"}]', '{"adjective":"attainable","noun":"attainment"}', NULL, 2, 464, NULL),
(465, 'attempt', '/əˈtempt/', 'verb', '{"zh-TW":["嘗試；企圖"],"en":["to try to do something, especially difficult","to try to do something"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tempt","meaning":"try (嘗試)"},"logic":"朝向嘗試，即「企圖」。"}', 'attempt to do / make an attempt; attempt to / first attempt / make an attempt', '[{"en":"The company attempted to enter the European market.","zh-TW":"公司嘗試進入歐洲市場。"},{"en":"Several attempts were made to resolve the dispute.","zh-TW":"多次嘗試解決爭端。"},{"en":"He attempted to climb the mountain alone.","zh-TW":"他嘗試獨自攀登那座山。"},{"en":"She passed the exam on her first attempt.","zh-TW":"她第一次嘗試就通過了考試。"}]', '{"noun":"attempt"}', NULL, 3, 465, NULL),
(466, 'attend', '/əˈtend/', 'verb', '{"zh-TW":["【主要意義-動詞】出席；參加","【次要意義-動詞】照料；服侍；護理（病人）","【次要意義-動詞】處理；注意（attend to）"],"en":["[primary] to be present at an event or place","[secondary] to care for someone who is sick or in need","[secondary] to deal with something; to give attention to"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tend","meaning":"stretch (延伸)"},"logic":"朝向延伸注意力，即「出席」。"}', 'attend to a matter / attend to a customer / attend on someone', '[{"en":"A doctor attended to the injured worker on site.","zh-TW":"現場有醫生照料受傷的工人。"},{"en":"Please attend to the urgent client inquiry before anything else.","zh-TW":"請在處理其他事情之前先處理緊急的客戶詢問。"},{"en":"The sales representative attended to each customer personally.","zh-TW":"銷售代表親自服務每位顧客。"}]', '{"noun":"attendant, attendance","adjective":"attentive"}', 'attend to = 「照料/服侍/處理」，不同於 attend（出席），是 TOEIC 客服或醫療文章中的陷阱用法，attendant（服務員/侍者）的詞根含義也源於此。', 2, 466, NULL),
(467, 'attendance record', '/''əˈtendəns ˌrekərd/', 'noun', '{"zh-TW":["出勤記錄；到課紀錄"],"en":["a record of a student''s presence or absence from classes"]}', NULL, 'maintain an attendance record / perfect attendance record / check attendance record', '[{"en":"A strong attendance record is often required for scholarship eligibility.","zh-TW":"強大的出勤記錄通常是獎學金資格的要求。"},{"en":"The system automatically updates attendance records each day.","zh-TW":"系統每天自動更新出勤記錄。"}]', NULL, NULL, 5, 467, NULL),
(468, 'attention', '/əˈtɛnʃən/', 'noun', '{"zh-TW":["注意力；關注","注意；關注"],"en":["the act of concentrating on something","the act of thinking about or watching something carefully"]}', NULL, 'pay attention / draw attention to; pay attention to / attract/draw attention', '[{"en":"Pay attention to the safety guidelines.","zh-TW":"請注意安全指南。"},{"en":"The report drew attention to the issue.","zh-TW":"報告引起了人們對該問題的關注。"},{"en":"Please pay attention to the instructions.","zh-TW":"請注意指示。"},{"en":"The advertisement attracted a lot of attention.","zh-TW":"這則廣告引起了很多關注。"}]', '{"noun":"attention","adjective":"attentive","adverb":"attentively"}', NULL, 3, 468, NULL),
(469, 'attitude', '/ˈætɪtjuːd/', 'noun', '{"zh-TW":["態度；看法"],"en":["a settled way of thinking or feeling about something"]}', '{"root":{"text":"apt","meaning":"fit (適合)"},"suffix":{"text":"-itude","meaning":"state (狀態)"},"logic":"適合的狀態展現，即「態度」。"}', 'positive/negative attitude / attitude toward', '[{"en":"A positive attitude is valued in the workplace.","zh-TW":"工作場所重視積極的態度。"},{"en":"Her attitude toward work impressed her supervisors.","zh-TW":"她對工作的態度令主管印象深刻。"}]', NULL, NULL, 3, 469, NULL),
(470, 'attorney', '/əˈtɜːrni/', 'noun', '{"zh-TW":["律師"],"en":["a person qualified to practice law"]}', NULL, 'attorney general / defense attorney', '[{"en":"She hired an attorney.","zh-TW":"她請了一位律師。"},{"en":"The attorney general issued a statement.","zh-TW":"總檢察長發表了聲明。"}]', NULL, NULL, 3, 470, NULL),
(471, 'attract', '/əˈtrækt/', 'verb', '{"zh-TW":["吸引；招引","吸引"],"en":["to cause to come to a place or participate","to draw someone''s attention or interest"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tract","meaning":"draw/pull (拉)"},"logic":"朝向拉來，即「吸引」。"}', 'attract customers/investors/talent; attract attention / attract customers / attract investment', '[{"en":"The campaign attracted thousands of new customers.","zh-TW":"該活動吸引了數千名新客戶。"},{"en":"We need to attract top talent to remain competitive.","zh-TW":"我們需要吸引頂尖人才以保持競爭力。"},{"en":"The new store attracted many customers.","zh-TW":"新店吸引了許多顧客。"},{"en":"Bright colors attract children''s attention.","zh-TW":"鮮艷的顏色吸引孩子的注意力。"}]', '{"noun":"attraction","adjective":"attractive"}', NULL, 3, 471, 272),
(472, 'attribute', '/əˈtrɪbjuːt/', 'verb', '{"zh-TW":["歸因於；認為是"],"en":["to regard something as being caused by"]}', '{"prefix":{"text":"at-","meaning":"toward (朝向)"},"root":{"text":"tribute","meaning":"assign (分配)"},"logic":"朝向分配原因，即「歸因於」。"}', 'attribute success/failure to', '[{"en":"She attributes her success to hard work and determination.","zh-TW":"她將成功歸因於努力和決心。"},{"en":"The decline was attributed to market conditions.","zh-TW":"下降被歸因於市場狀況。"}]', '{"noun":"attribution"}', NULL, 3, 472, 650),
(473, 'attribution', '/ˌætrɪˈbjuːʃən/', 'noun', '{"zh-TW":["歸因；歸屬"],"en":["the action of regarding a quality or feature as belonging to someone or something"]}', NULL, 'correct attribution / source attribution / attribution analysis', '[{"en":"Proper attribution of sources is required in academic writing.","zh-TW":"學術寫作中需要適當的來源歸因。"},{"en":"Attribution analysis helps investors understand which factors drove portfolio returns.","zh-TW":"歸因分析幫助投資者了解哪些因素推動了投資組合的回報。"}]', '{"verb":"attribute","adjective":"attributable"}', NULL, 4, 473, NULL),
(474, 'attribution model', '/ˌætrɪˈbjuːʃən ˈmɒdəl/', 'noun', '{"zh-TW":["歸因模型"],"en":["a framework for determining which marketing activities drove a conversion"]}', NULL, 'multi-touch attribution model / last-click attribution model', '[{"en":"The attribution model showed that email drove most conversions.","zh-TW":"歸因模型顯示電子郵件推動了最多的轉換。"},{"en":"Choosing the right attribution model is critical for measuring ROI.","zh-TW":"選擇正確的歸因模型對衡量投資報酬率至關重要。"}]', NULL, NULL, 5, 474, NULL),
(475, 'attrition', '/əˈtrɪʃən/', 'noun', '{"zh-TW":["自然減員；磨損"],"en":["the reduction in staff through voluntary departures without replacement"]}', NULL, 'natural attrition / attrition rate / high attrition', '[{"en":"The company relied on attrition rather than layoffs to reduce headcount.","zh-TW":"公司依靠自然減員而非裁員來減少人數。"},{"en":"High attrition in the sales team raised concerns about culture.","zh-TW":"銷售團隊的高自然減員率引發了對企業文化的擔憂。"}]', '{"adjective":"attritive"}', NULL, 3, 475, 750),
(476, 'attrition rate', '/əˈtrɪʃən reɪt/', 'noun', '{"zh-TW":["自然減員率；人員流失率"],"en":["the rate at which employees leave a company over time and are not replaced"]}', NULL, 'reduce attrition rate / high attrition rate / measure attrition rate', '[{"en":"The high attrition rate signaled serious problems with employee morale and management.","zh-TW":"高人員流失率表明員工士氣和管理存在嚴重問題。"},{"en":"Improving working conditions is the most effective way to reduce the attrition rate.","zh-TW":"改善工作條件是降低人員流失率最有效的方法。"}]', '{"noun":"attrition","adjective":"attritional"}', NULL, 5, 476, NULL),
(477, 'auction', '/ˈɔːkʃən/', 'noun', '{"zh-TW":["拍賣"],"en":["a public sale in which goods or property are sold to the highest bidder"]}', NULL, 'public auction / online auction / put up for auction', '[{"en":"The seized assets were sold at a public auction.","zh-TW":"被沒收的資產在公開拍賣會上出售。"},{"en":"She won the bid at the online auction for the collectibles.","zh-TW":"她在線上拍賣會上以最高出價獲得了藏品。"}]', '{"verb":"auction","noun":"auctioneer"}', NULL, 3, 477, NULL),
(478, 'audience', '/ˈɔːdiəns/', 'noun', '{"zh-TW":["觀眾；聽眾"],"en":["people watching or listening to a performance"]}', NULL, 'target audience / live audience', '[{"en":"The audience applauded loudly.","zh-TW":"觀眾大聲鼓掌。"},{"en":"The show attracted a large audience.","zh-TW":"這個節目吸引了大量觀眾。"}]', NULL, NULL, 3, 478, NULL),
(479, 'audio guide', '/''ɔːdiəʊ ɡaɪd/', 'noun', '{"zh-TW":["語音導覽；語音指南"],"en":["a recording providing commentary or information about a place of interest"]}', NULL, 'rent an audio guide / audio guide headset / download an audio guide', '[{"en":"An audio guide is available in twelve languages at the visitor center.","zh-TW":"遊客中心提供十二種語言的語音導覽。"},{"en":"The audio guide explained the history behind each painting in the gallery.","zh-TW":"語音導覽解釋了畫廊中每幅畫作背後的歷史。"}]', NULL, NULL, 4, 479, NULL),
(480, 'audit', '/ˈɔːdɪt/', 'noun', '{"zh-TW":["審計；稽核"],"en":["an official examination of accounts or processes"]}', '{"root":{"text":"audit","meaning":"hear (聽)"},"logic":"最初為聽取帳目報告，即「審計」。"}', 'conduct an audit / annual audit', '[{"en":"The firm conducts an annual financial audit.","zh-TW":"該公司進行年度財務審計。"},{"en":"An internal audit revealed several discrepancies.","zh-TW":"內部稽核揭露了幾項差異。"}]', '{"noun":"auditor"}', NULL, 2, 480, 273),
(481, 'audit committee', '/ˈɔːdɪt kəˈmɪti/', 'noun', '{"zh-TW":["審計委員會"],"en":["a board committee overseeing financial reporting and audit processes"]}', NULL, 'appoint an audit committee / audit committee meeting', '[{"en":"The audit committee reviewed the external auditor''s findings.","zh-TW":"審計委員會審查了外部審計師的調查結果。"},{"en":"An independent audit committee is required for listed companies.","zh-TW":"上市公司需要設立獨立的審計委員會。"}]', NULL, NULL, 5, 481, NULL),
(482, 'audit trail', '/ˈɔːdɪt treɪl/', 'noun', '{"zh-TW":["審計追蹤；稽核軌跡"],"en":["a documented record of all transactions and changes for accountability"]}', NULL, 'maintain an audit trail / complete audit trail / audit trail review', '[{"en":"The audit trail showed every change made to the financial records.","zh-TW":"審計追蹤顯示了對財務記錄所做的每一項更改。"},{"en":"A complete audit trail is required for compliance purposes.","zh-TW":"合規目的需要完整的審計追蹤。"}]', NULL, NULL, 4, 482, NULL),
(483, 'auditor', '/ˈɔːdɪtər/', 'noun', '{"zh-TW":["審計師；稽核人員"],"en":["a person who conducts an official examination of financial records"]}', NULL, 'external auditor / internal auditor / appoint an auditor', '[{"en":"The auditor found discrepancies in the accounts.","zh-TW":"審計師在帳目中發現了差異。"},{"en":"The firm''s auditor issued a clean audit opinion.","zh-TW":"公司的審計師發表了無保留意見。"}]', '{"plural":"auditors"}', NULL, 3, 483, NULL),
(484, 'augment', '/ɔːɡˈment/', 'verb', '{"zh-TW":["增加；擴充"],"en":["to make something greater by adding to it"]}', NULL, 'augment resources / augment capabilities / augment the workforce', '[{"en":"Companies use freelancers to augment their full-time workforce.","zh-TW":"公司使用自由工作者來擴充其全職勞動力。"},{"en":"Wearable sensors augment the doctor''s ability to monitor patients remotely.","zh-TW":"可穿戴感測器增強了醫生遠程監測患者的能力。"}]', '{"noun":"augmentation","adjective":"augmented"}', NULL, 3, 484, NULL),
(485, 'auspicious', '/''ɔːˌspɪʃəs/', 'adjective', '{"zh-TW":["吉利的；有利的"],"en":["conducive to success; favorable; giving or being a sign of future success"]}', NULL, 'auspicious start / auspicious occasion / auspicious sign', '[{"en":"The new product launch had an auspicious start with record first-day sales.","zh-TW":"新產品發布有了一個吉利的開始，第一天創下了銷售記錄。"},{"en":"She chose an auspicious date for signing the contract, according to cultural tradition.","zh-TW":"她根據文化傳統，選擇了一個吉利的日期簽署合同。"}]', '{"adverb":"auspiciously","noun":"auspice"}', NULL, 4, 485, NULL),
(486, 'austerity', '/ɒˈsterɪti/', 'noun', '{"zh-TW":["緊縮；節約"],"en":["government policies cutting spending to reduce budget deficits"]}', NULL, 'austerity measures / period of austerity / implement austerity', '[{"en":"The government introduced austerity measures to reduce the deficit.","zh-TW":"政府引入緊縮措施以削減赤字。"},{"en":"Years of austerity reduced public services significantly.","zh-TW":"多年的緊縮政策顯著縮減了公共服務。"}]', '{"adjective":"austere"}', NULL, 3, 486, NULL),
(487, 'auteur', '/ɒˈtɜːr/', 'noun', '{"zh-TW":["作者型導演；藝術創作者"],"en":["a filmmaker who has a distinctive personal style and creative control"]}', NULL, 'celebrated auteur / auteur theory / independent auteur', '[{"en":"The auteur crafted a deeply personal film that divided critics.","zh-TW":"這位作者型導演創作了一部極為個人化的電影，引發評論兩極分化。"},{"en":"Auteur theory credits directors as the primary authors of films.","zh-TW":"作者論認為導演是電影的主要作者。"}]', NULL, NULL, 2, 487, NULL),
(488, 'authentic', '/ɔːˈθentɪk/', 'adjective', '{"zh-TW":["真實的；正宗的"],"en":["genuine; of undisputed origin"]}', '{"root":{"text":"authent","meaning":"original (原始的)"},"suffix":{"text":"-ic","meaning":"relating to (相關的)"},"logic":"與原始真實相關的，即「正宗的」。"}', 'authentic cuisine / authentic experience', '[{"en":"This restaurant serves authentic Italian food.","zh-TW":"這家餐廳供應正宗義大利料理。"},{"en":"Is this an authentic Gucci bag?","zh-TW":"這是正品Gucci包嗎？"}]', '{"noun":"authenticity","adverb":"authentically"}', NULL, 3, 488, NULL),
(489, 'authenticate', 'ɔːˈθɛntɪkeɪt', 'verb', '{"zh-TW":["驗證；認證","確認真實性"],"en":["to prove something is genuine","to verify"]}', NULL, 'authenticate a user/authenticate documents', '[{"en":"Please authenticate your identity.","zh-TW":"請驗證您的身份。"}]', '{"noun":"authentication","adjective":"authenticated"}', NULL, 4, 489, NULL),
(490, 'authorised capital', '/ˈɔːθəraɪzd ˈkæpɪtəl/', 'noun', '{"zh-TW":["授權資本；法定股本"],"en":["the maximum amount of share capital a company is permitted to issue"]}', NULL, 'increase authorised capital / authorised capital structure', '[{"en":"The company increased its authorised capital to allow a larger share issuance.","zh-TW":"公司增加了其授權資本以允許更大規模的股票發行。"},{"en":"Authorised capital sets an upper limit on the shares a company may sell.","zh-TW":"授權資本設定了公司可出售股份的上限。"}]', '{"synonym":"authorized share capital"}', NULL, 5, 490, NULL),
(491, 'authority', '/ɔːˈθɒrəti/', 'noun', '{"zh-TW":["權威；當局"],"en":["the power to give orders","an organization with official power"]}', '{"root":{"text":"author","meaning":"originator (創始者)"},"suffix":{"text":"-ity","meaning":"state of (狀態)"},"logic":"身為創始者的地位，即「權威」。"}', 'local authority / authority figure / have authority', '[{"en":"The local authority approved the building plan.","zh-TW":"地方當局批准了建築計畫。"},{"en":"He spoke with authority on the subject.","zh-TW":"他在這個議題上很有權威。"}]', '{"adjective":"authoritative","verb":"authorize","noun2":"authorization"}', NULL, 3, 491, 274),
(492, 'authorization', '/ˌɔːθərɪˈzeɪʃən/', 'noun', '{"zh-TW":["授權；批准"],"en":["official permission or power to do something"]}', NULL, 'obtain authorization / require authorization', '[{"en":"Please obtain authorization before accessing restricted files.","zh-TW":"訪問受限文件前請先獲得授權。"},{"en":"Payment authorization was granted by the finance director.","zh-TW":"付款授權由財務主管批准。"}]', '{"verb":"authorize","adjective":"authorized"}', NULL, 5, 492, 511),
(493, 'authorization level', '/ˌɔːθərɪˈzeɪʃən ˈlevəl/', 'noun', '{"zh-TW":["授權級別"],"en":["the limit of spending or approval authority assigned to a role or individual"]}', NULL, 'set authorization levels / authorization level exceeded', '[{"en":"Purchases above $10000 require manager authorization level approval.","zh-TW":"超過10,000元的採購需要經理授權級別的批准。"},{"en":"The authorization level for capital expenditure was raised to $50000.","zh-TW":"資本支出的授權級別提高到了5萬元。"}]', NULL, NULL, 5, 493, NULL),
(494, 'authorize', '/ˈɔːθəraɪz/', 'verb', '{"zh-TW":["授權；批准"],"en":["to give official permission for something"]}', '{"root":{"text":"author","meaning":"creator (創造者)"},"suffix":{"text":"-ize","meaning":"to make (使)"},"logic":"使成為有權者，即「授權」。"}', 'authorize payment/access/use', '[{"en":"Only the director can authorize expenditures over $10,000.","zh-TW":"只有主管可以授權超過10,000美元的支出。"},{"en":"The transaction was not authorized.","zh-TW":"該交易未獲授權。"}]', '{"noun":"authorization","adjective":"authorized"}', NULL, 3, 494, 75),
(495, 'authorized dealer', '/ˈɔːθəraɪzd ˈdiːlər/', 'noun', '{"zh-TW":["授權經銷商"],"en":["a seller officially approved by a manufacturer to sell its products"]}', NULL, 'become an authorized dealer / authorized dealer network', '[{"en":"Only purchase from an authorized dealer to ensure product authenticity.","zh-TW":"只從授權經銷商購買以確保產品真實性。"},{"en":"The authorized dealer program expanded to 50 locations.","zh-TW":"授權經銷商計劃擴展到了50個地點。"}]', NULL, NULL, 5, 495, NULL),
(496, 'automated', 'ˈɔːtəmeɪtɪd', 'adjective', '{"zh-TW":["自動化的；自動的","機械化的"],"en":["using automatic equipment","operated without manual control"]}', NULL, 'automated system/automated report', '[{"en":"The automated system generates weekly reports.","zh-TW":"自動化系統每週生成報告。"}]', '{"verb":"automate","noun":"automation"}', NULL, 3, 496, NULL),
(497, 'automatic', '/ˌɔːtəˈmætɪk/', 'adjective', '{"zh-TW":["自動的"],"en":["operating by itself with little human control"]}', '{"root":{"text":"auto","meaning":"self (自己)"},"suffix":{"text":"-matic","meaning":"acting (行動的)"},"logic":"自己行動的，即「自動的」。"}', 'automatic update/renewal/response; automatic transmission / automatic reply / fully automatic', '[{"en":"The system sends automatic email confirmations.","zh-TW":"系統會發送自動電子郵件確認。"},{"en":"Payments are processed automatically each month.","zh-TW":"付款每月自動處理。"},{"en":"The doors open automatically.","zh-TW":"門會自動開啟。"},{"en":"The system sends automatic reminders.","zh-TW":"系統會發送自動提醒。"}]', '{"adverb":"automatically","noun":"automation","verb":"automate"}', NULL, 3, 497, NULL),
(498, 'automatic renewal', '/ˌɔːtəˈmætɪk rɪˈnjuːəl/', 'noun', '{"zh-TW":["自動續約"],"en":["the extension of a contract for another term without requiring affirmative action"]}', NULL, 'automatic renewal clause / opt out of automatic renewal', '[{"en":"The subscription had an automatic renewal clause unless cancelled in advance.","zh-TW":"訂閱有自動續約條款，除非提前取消。"},{"en":"Customers must be notified before an automatic renewal takes effect.","zh-TW":"在自動續約生效之前，必須通知客戶。"}]', NULL, NULL, 5, 498, NULL),
(499, 'automation', '/ˌɔːtəˈmeɪʃən/', 'noun', '{"zh-TW":["自動化"],"en":["using technology to perform tasks with minimal human intervention"]}', NULL, 'process automation / robotic automation / automation technology / workflow automation', '[{"en":"Automation reduced the time needed for data entry by 80%.","zh-TW":"自動化將數據輸入所需時間減少了80%。"},{"en":"The factory''s automation increased output while reducing labor costs.","zh-TW":"工廠自動化在降低勞動成本的同時提高了產量。"}]', '{"verb":"automate","adjective":"automated","noun":"automator"}', NULL, 4, 499, 275);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(500, 'autonomous vehicle', '/ɔːˈtɒnəməs ˈviːɪkəl/', 'noun', '{"zh-TW":["自駕車；自動駕駛車輛"],"en":["a vehicle capable of navigating without human input"]}', NULL, 'deploy autonomous vehicles / test autonomous vehicles / autonomous vehicle technology', '[{"en":"Autonomous vehicles use sensors and AI to navigate roads safely.","zh-TW":"自駕車使用感測器和人工智慧安全導航道路。"},{"en":"Regulatory frameworks for autonomous vehicles are still being developed.","zh-TW":"自駕車的監管框架仍在制定中。"}]', '{"adjective":"autonomous"}', NULL, 5, 500, NULL),
(501, 'autonomy', '/ɔːˈtɒnəmi/', 'noun', '{"zh-TW":["自主；自主權"],"en":["freedom to act independently without external control"]}', NULL, 'organizational autonomy / operational autonomy / give autonomy', '[{"en":"Subsidiaries operate with a high degree of autonomy.","zh-TW":"子公司以高度自主的方式運營。"},{"en":"Employees with more autonomy tend to show greater job satisfaction.","zh-TW":"擁有更多自主權的員工往往表現出更高的工作滿意度。"}]', '{"adjective":"autonomous","adverb":"autonomously"}', NULL, 3, 501, NULL),
(502, 'autumn', '/ˈɔːtəm/', 'noun', '{"zh-TW":["秋天"],"en":["the season between summer and winter"]}', NULL, 'autumn season / in autumn; in autumn / autumn leaves', '[{"en":"Sales typically increase in autumn.","zh-TW":"銷售額通常在秋季增加。"},{"en":"The autumn collection launches next week.","zh-TW":"秋季系列下週發布。"},{"en":"Leaves change color in autumn.","zh-TW":"秋天葉子會變色。"},{"en":"Autumn is my favorite season.","zh-TW":"秋天是我最喜歡的季節。"}]', '{"noun":"autumn","adjective":"autumnal"}', NULL, 2, 502, NULL),
(503, 'availability', '/əˌveɪləˈbɪlɪti/', 'noun', '{"zh-TW":["可用性；空房情況"],"en":["the state of being available or accessible"]}', NULL, 'room availability / check availability', '[{"en":"Please check room availability for the dates you need.","zh-TW":"請查看您所需日期的房間空房情況。"},{"en":"Availability is limited during the holiday season.","zh-TW":"假日期間可用性有限。"}]', '{"verb":"avail","adjective":"available"}', NULL, 4, 503, 957),
(504, 'available', '/əˈveɪləbl/', 'adjective', '{"zh-TW":["可用的；可獲得的"],"en":["able to be used or obtained"]}', '{"root":{"text":"avail","meaning":"be strong/be of use (有用)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠被使用的，即「可用的」。"}', 'available for / currently available', '[{"en":"The product is now available in all major stores.","zh-TW":"該產品現已在所有主要商店有售。"},{"en":"I''m available for a meeting on Thursday afternoon.","zh-TW":"我週四下午有空開會。"}]', '{"noun":"availability"}', NULL, 3, 504, 11),
(505, 'avalanche', '/ˈævəlæntʃ/', 'noun', '{"zh-TW":["雪崩"],"en":["a mass of snow falling rapidly down a mountainside"]}', '{"root":{"text":"avalanche","meaning":"descend (滑落)"},"logic":"源自法語 avaler（下降），指雪的快速滑落。"}', 'trigger an avalanche / avalanche warning', '[{"en":"The avalanche buried the entire village.","zh-TW":"雪崩掩埋了整個村莊。"},{"en":"Skiers should be aware of avalanche risks.","zh-TW":"滑雪者應注意雪崩風險。"}]', NULL, NULL, 3, 505, NULL),
(506, 'avant-garde', '/ˌævɒ̃ ˈɡɑːrd/', 'adjective', '{"zh-TW":["前衛的；先鋒的"],"en":["new and experimental in ideas or art"]}', NULL, 'avant-garde art / avant-garde movement / avant-garde style', '[{"en":"The gallery exhibited avant-garde sculptures that challenged conventional forms.","zh-TW":"畫廊展出了挑戰傳統形式的前衛雕塑。"},{"en":"Avant-garde music often alienates mainstream audiences at first.","zh-TW":"前衛音樂最初往往讓主流觀眾感到陌生。"}]', '{"noun":"avant-garde"}', NULL, 4, 506, NULL),
(507, 'average', 'ˈævərɪdʒ', 'noun', '{"zh-TW":["平均；一般水準","平均值"],"en":["the middle value of a group","a usual level"]}', NULL, 'on average/industry average', '[{"en":"The average salary in this sector is high.","zh-TW":"這個行業的平均薪資很高。"}]', '{"adjective":"average","adverb":"on average"}', NULL, 3, 507, NULL),
(508, 'average collection period', '/ˈævərɪdʒ kəˈlekʃən ˈpɪəriəd/', 'noun', '{"zh-TW":["平均收款期"],"en":["the average number of days it takes to collect payment after a sale"]}', NULL, 'calculate average collection period / shorten average collection period', '[{"en":"The average collection period decreased from 45 to 30 days.","zh-TW":"平均收款期從45天縮短到了30天。"},{"en":"A shorter average collection period improves cash flow management.","zh-TW":"較短的平均收款期改善了現金流管理。"}]', NULL, NULL, 5, 508, NULL),
(509, 'avoid', '/əˈvɔɪd/', 'verb', '{"zh-TW":["避免；迴避"],"en":["to keep away from or stop oneself from doing"]}', '{"prefix":{"text":"a-","meaning":"away (離開)"},"root":{"text":"void","meaning":"empty (空)"},"logic":"使離開空虛（危險），即「避免」。"}', 'avoid risk/mistakes/delays', '[{"en":"To avoid delays, please submit your documents early.","zh-TW":"為避免延遲，請提早提交文件。"},{"en":"The company took steps to avoid further losses.","zh-TW":"公司採取措施避免進一步損失。"}]', '{"adjective":"avoidable","noun":"avoidance"}', NULL, 2, 509, NULL),
(510, 'awake', '/əˈweɪk/', 'adjective', '{"zh-TW":["醒著的"],"en":["not sleeping"]}', NULL, 'wide awake / stay awake', '[{"en":"Are you still awake?","zh-TW":"你還醒著嗎？"},{"en":"I lay awake all night.","zh-TW":"我整晚都醒著。"}]', '{"verb":"awaken"}', NULL, 2, 510, NULL),
(511, 'award', '/əˈwɔːrd/', 'noun', '{"zh-TW":["獎項；獎金","授予","獎；獎項"],"en":["a prize given for achievement","to officially give something as a reward"]}', '{"prefix":{"text":"a-","meaning":"toward (朝向)"},"root":{"text":"ward","meaning":"guard/watch (看守)"},"logic":"朝向看守評定後給予，即「獎項」。"}', 'award a contract/prize/grant; award ceremony / win an award', '[{"en":"The contract was awarded to the lowest bidder.","zh-TW":"合約授予了最低出價者。"},{"en":"She received an award for outstanding performance.","zh-TW":"她因傑出表現獲得獎項。"},{"en":"She won an award for best actress.","zh-TW":"她獲得了最佳女主角獎。"},{"en":"The awards ceremony is tonight.","zh-TW":"頒獎典禮今晚舉行。"}]', '{"verb":"award"}', NULL, 2, 511, NULL),
(512, 'aware', 'əˈwɛr', 'adjective', '{"zh-TW":["意識到的；知道的","了解的"],"en":["having knowledge of something","conscious of"]}', NULL, 'be aware of/fully aware', '[{"en":"Please be aware of the new policy.","zh-TW":"請注意新政策。"}]', '{"noun":"awareness","adverb":"with awareness"}', NULL, 2, 512, 276),
(513, 'axiom', '/ˈæksiəm/', 'noun', '{"zh-TW":["公理；自明之理"],"en":["a statement accepted as true without proof"]}', NULL, 'fundamental axiom / basic axiom / accept an axiom', '[{"en":"It is an axiom that markets seek equilibrium.","zh-TW":"市場尋求均衡是一個公理。"},{"en":"The researcher challenged the prevailing axiom of the field.","zh-TW":"研究員挑戰了該領域的主流公理。"}]', '{"adjective":"axiomatic","adverb":"axiomatically"}', NULL, 2, 513, NULL),
(514, 'B2B', '/ˌbiː tə ˈbiː/', 'adjective', '{"zh-TW":["企業對企業的；B2B"],"en":["business to business; transactions between companies"]}', NULL, 'B2B sales / B2B marketing / B2B e-commerce / B2B platform', '[{"en":"The company shifted its focus from B2C to B2B customers.","zh-TW":"公司將重心從消費者市場轉向企業客戶。"},{"en":"B2B sales cycles are typically longer than consumer sales.","zh-TW":"B2B銷售週期通常比消費者銷售更長。"}]', '{"full form":"business to business"}', NULL, 1, 514, NULL),
(515, 'B2C', '/ˌbiː tə ˈsiː/', 'adjective', '{"zh-TW":["企業對消費者的；B2C"],"en":["business to consumer; transactions between a company and individual consumers"]}', NULL, 'B2C marketing / B2C platform / B2C e-commerce', '[{"en":"The new product line targets B2C customers through retail channels.","zh-TW":"新產品線通過零售渠道針對消費者客戶。"},{"en":"B2C brands invest heavily in social media advertising.","zh-TW":"B2C品牌在社群媒體廣告上投入大量資金。"}]', '{"full form":"business to consumer"}', NULL, 1, 515, NULL),
(516, 'baby', '/ˈbeɪbi/', 'noun', '{"zh-TW":["嬰兒；寶寶"],"en":["a very young child"]}', NULL, 'have a baby / baby products; baby shower / have a baby; baby shower / baby boom', '[{"en":"She is on maternity leave after having a baby.","zh-TW":"她生完孩子後在休產假。"},{"en":"Baby products are on the second floor.","zh-TW":"嬰兒用品在二樓。"},{"en":"The baby is sleeping.","zh-TW":"寶寶正在睡覺。"},{"en":"They''re having a baby next month.","zh-TW":"他們下個月要生寶寶了。"},{"en":"The baby is sleeping.","zh-TW":"寶寶在睡覺。"},{"en":"She''s expecting a baby in June.","zh-TW":"她預計六月生寶寶。"}]', '{"noun":"baby","adjective":"babyish"}', NULL, 1, 516, NULL),
(517, 'back', '/bæk/', 'noun', '{"zh-TW":["背部；後面","背部；後面；回去；支持"],"en":["the rear part of the body or thing","the rear part; to a previous position; to support"]}', NULL, 'go back / back and forth; go back / back up / at the back of', '[{"en":"My back hurts.","zh-TW":"我的背很痛。"},{"en":"I''ll be back in an hour.","zh-TW":"我一小時後回來。"},{"en":"He sat at the back of the room.","zh-TW":"他坐在房間後面。"},{"en":"I''ll be back in five minutes.","zh-TW":"我五分鐘後回來。"}]', '{"noun":"background, backup","adjective":"backward"}', NULL, 1, 517, NULL),
(518, 'back office', '/bæk ˈɒfɪs/', 'noun', '{"zh-TW":["後台；後勤辦公室"],"en":["the administrative and support functions of a business not visible to clients"]}', NULL, 'manage back office operations / back office system', '[{"en":"The bank upgraded its back office software to reduce processing errors.","zh-TW":"銀行升級了後台軟件以減少處理錯誤。"},{"en":"Back office functions include accounting, IT, and compliance.","zh-TW":"後台功能包括會計、IT和合規。"}]', '{"opposite":"front office"}', NULL, 4, 518, NULL),
(519, 'back order', '/bæk ˈɔːrdər/', 'noun', '{"zh-TW":["待補貨訂單；延遲交貨訂單"],"en":["an order placed for goods that are currently out of stock"]}', NULL, 'place a back order / back order fulfillment', '[{"en":"Customers were notified that their orders were placed on back order.","zh-TW":"客戶被告知其訂單處於待補貨狀態。"},{"en":"The warehouse worked overtime to fulfill outstanding back orders.","zh-TW":"倉庫加班以完成未結的待補貨訂單。"}]', '{"verb":"back order"}', NULL, 4, 519, NULL),
(520, 'back-office operations', '/bæk ˈɒfɪs ˌɒpəˈreɪʃənz/', 'noun', '{"zh-TW":["後台運營"],"en":["administrative and support activities that are not customer-facing"]}', NULL, 'improve back-office operations / automate back-office operations', '[{"en":"Automating back-office operations reduced processing time by 40%.","zh-TW":"自動化後台運營將處理時間縮短了40%。"},{"en":"Back-office operations include transaction processing and compliance reporting.","zh-TW":"後台運營包括交易處理和合規報告。"}]', NULL, NULL, 5, 520, NULL),
(521, 'background', '/ˈbækˌɡraʊnd/', 'noun', '{"zh-TW":["背景；背景資料"],"en":["a person''s history, education, or experience"]}', NULL, 'professional background / background check', '[{"en":"Her background in finance made her ideal for the role.","zh-TW":"她的金融背景使她非常適合這個職位。"},{"en":"A background check is required before the job offer is confirmed.","zh-TW":"在確認錄用前需要進行背景調查。"}]', NULL, NULL, 4, 521, 512),
(522, 'background check', '/ˈbækˌɡraʊnd tʃek/', 'noun', '{"zh-TW":["背景調查"],"en":["verification of an applicant''s personal history and credentials"]}', NULL, 'conduct a background check / pass a background check / pre-employment background check', '[{"en":"All applicants must pass a background check before being hired.","zh-TW":"所有申請者在被錄用前必須通過背景調查。"},{"en":"The background check revealed a discrepancy in the resume.","zh-TW":"背景調查發現了簡歷中的差異。"}]', '{"verb":"run a background check"}', NULL, 5, 522, NULL),
(523, 'backlog', '/ˈbæklɒɡ/', 'noun', '{"zh-TW":["待辦清單；積壓工作"],"en":["a list of tasks or features yet to be completed, prioritized for future work"]}', NULL, 'product backlog / backlog grooming / clear the backlog / backlog item', '[{"en":"The product backlog was reviewed and prioritized at the start of each sprint.","zh-TW":"產品待辦清單在每個衝刺開始時進行審查和優先排序。"},{"en":"The team worked through the backlog of support tickets.","zh-TW":"團隊處理了積壓的支援票務。"}]', '{"verb":"backlog"}', NULL, 3, 523, 751),
(524, 'backlog of orders', '/ˈbæklɒɡ əv ˈɔːrdərz/', 'noun', '{"zh-TW":["積壓訂單"],"en":["a build-up of unfilled customer orders awaiting fulfillment"]}', NULL, 'reduce the backlog of orders / backlog of orders indicator', '[{"en":"The backlog of orders grew to three weeks as production was delayed.","zh-TW":"隨著生產延誤，積壓訂單增長到了三週。"},{"en":"A rising backlog of orders indicates strong demand and potential revenue.","zh-TW":"不斷增長的積壓訂單表明了強勁的需求和潛在收入。"}]', NULL, NULL, 5, 524, NULL),
(525, 'backorder', '/ˈbækˌɔːrdər/', 'noun', '{"zh-TW":["延期交貨訂單；積壓訂單"],"en":["an order that cannot be fulfilled immediately due to lack of stock"]}', NULL, 'place on backorder / clear backorders / high backorder rate', '[{"en":"Demand surged and many items were placed on backorder.","zh-TW":"需求激增，許多商品被列為延期交貨。"},{"en":"The factory worked overtime to clear the backorder queue.","zh-TW":"工廠加班以清理積壓訂單。"}]', '{"verb":"backorder","adjective":"backordered"}', NULL, 3, 525, NULL),
(526, 'backpacker', '/''bækˌpækər/', 'noun', '{"zh-TW":["背包客"],"en":["a person who travels with minimal luggage carrying a backpack"]}', NULL, 'budget backpacker / solo backpacker / experienced backpacker', '[{"en":"Many backpackers stay in hostels to save money.","zh-TW":"許多背包客住在青年旅舍以節省費用。"},{"en":"She spent a year as a backpacker traveling through Southeast Asia.","zh-TW":"她花了一年時間作為背包客遊覽東南亞。"}]', '{"noun":"backpacking","verb":"backpack"}', NULL, 4, 526, NULL),
(527, 'backpacking trip', '/''bækˌpækɪŋ trɪp/', 'noun', '{"zh-TW":["背包旅行；自助旅行"],"en":["a low-budget trip where the traveler carries their belongings in a backpack"]}', NULL, 'plan a backpacking trip / go on a backpacking trip / solo backpacking trip', '[{"en":"A backpacking trip through Europe taught her independence and resourcefulness.","zh-TW":"穿越歐洲的背包旅行教會了她獨立和足智多謀。"},{"en":"He saved for two years to fund a six-month backpacking trip around the world.","zh-TW":"他存了兩年錢，資助了一次為期六個月的環球背包旅行。"}]', NULL, NULL, 5, 527, NULL),
(528, 'backpropagation', '/ˌbækˌprɒpəˈɡeɪʃən/', 'noun', '{"zh-TW":["反向傳播"],"en":["an algorithm used to train neural networks by adjusting weights"]}', NULL, 'backpropagation algorithm / apply backpropagation / gradient descent backpropagation', '[{"en":"Backpropagation is the core algorithm for training deep neural networks.","zh-TW":"反向傳播是訓練深度神經網路的核心算法。"},{"en":"The model improved accuracy through thousands of backpropagation iterations.","zh-TW":"模型通過數千次反向傳播迭代提高了準確性。"}]', NULL, NULL, 5, 528, NULL),
(529, 'backup', '/ˈbækʌp/', 'noun', '{"zh-TW":["備份"],"en":["a copy of data stored separately in case of loss"]}', NULL, 'create a backup / data backup', '[{"en":"Always create a backup of important files.","zh-TW":"務必對重要文件進行備份。"},{"en":"The system backup is scheduled to run at midnight.","zh-TW":"系統備份安排在午夜執行。"}]', '{"verb":"back up","adjective":"backed up"}', NULL, 2, 529, NULL),
(530, 'backward integration', '/ˈbækwərd ˌɪntɪˈɡreɪʃən/', 'noun', '{"zh-TW":["向後整合；向上游整合"],"en":["a strategy where a company acquires its suppliers to control upstream activities"]}', NULL, 'pursue backward integration / backward integration strategy', '[{"en":"Backward integration gave the company direct control over raw material supply.","zh-TW":"向後整合使公司直接控制了原材料供應。"},{"en":"Buying out a key supplier is a common backward integration approach.","zh-TW":"收購主要供應商是常見的向後整合方式。"}]', '{"opposite":"forward integration"}', NULL, 5, 530, NULL),
(531, 'bad', '/bæd/', 'adjective', '{"zh-TW":["壞的；糟糕的","壞的；糟糕的；嚴重的"],"en":["of poor quality; unpleasant","of poor quality; unpleasant; serious"]}', NULL, 'not bad / go bad; go bad (變壞) / not bad (還不錯)', '[{"en":"The weather is really bad today.","zh-TW":"今天天氣真的很糟。"},{"en":"The milk has gone bad.","zh-TW":"牛奶壞了。"},{"en":"The weather was really bad yesterday.","zh-TW":"昨天天氣真的很糟。"},{"en":"I feel bad about what happened.","zh-TW":"我對發生的事感到抱歉。"}]', '{"adverb":"badly","noun":"badness"}', NULL, 1, 531, NULL),
(532, 'bag', '/bæɡ/', 'noun', '{"zh-TW":["袋子；包","袋子；手提包"],"en":["a container made of flexible material","a container made of paper, plastic, cloth, or leather"]}', NULL, 'shopping bag / bag of tricks; shopping bag / handbag / luggage bag', '[{"en":"She put the books in her bag.","zh-TW":"她把書放進了包裡。"},{"en":"Can I have a plastic bag?","zh-TW":"可以給我一個塑膠袋嗎？"},{"en":"She put the groceries in a bag.","zh-TW":"她把雜貨放進袋子裡。"},{"en":"Don''t forget your bag.","zh-TW":"別忘了你的包。"}]', NULL, NULL, 1, 532, NULL),
(533, 'baggage', '/ˈbægɪdʒ/', 'noun', '{"zh-TW":["行李"],"en":["bags and suitcases used when traveling"]}', NULL, 'carry-on baggage / excess baggage', '[{"en":"Passengers are allowed one piece of carry-on baggage.","zh-TW":"乘客可攜帶一件手提行李。"},{"en":"The airline charges a fee for excess baggage.","zh-TW":"航空公司對超重行李收費。"}]', '{"verb":"pack","adjective":"excess"}', NULL, 3, 533, NULL),
(534, 'baggage allowance', '/ˈbægɪdʒ əˈlaʊəns/', 'noun', '{"zh-TW":["行李限額"],"en":["the weight or number of bags permitted on a flight"]}', NULL, 'exceed the baggage allowance / baggage allowance policy', '[{"en":"Passengers in economy class have a 23 kg baggage allowance.","zh-TW":"經濟艙乘客有23公斤的行李限額。"},{"en":"Check the baggage allowance before packing.","zh-TW":"打包前請查看行李限額。"}]', NULL, NULL, 5, 534, NULL),
(535, 'baggage carousel', '/''bæɡɪdʒ ˌkærəˈsel/', 'noun', '{"zh-TW":["行李轉盤"],"en":["a revolving conveyor belt at an airport on which checked baggage is delivered to arriving passengers"]}', NULL, 'wait at the baggage carousel / baggage carousel area / find the baggage carousel', '[{"en":"Passengers wait at the baggage carousel to collect their checked luggage.","zh-TW":"旅客在行李轉盤旁等待取回託運行李。"},{"en":"Her suitcase was one of the last bags to appear on the baggage carousel.","zh-TW":"她的手提箱是行李轉盤上最後出現的行李之一。"}]', NULL, NULL, 5, 535, NULL),
(536, 'baggage claim', '/ˈbægɪdʒ kleɪm/', 'noun', '{"zh-TW":["行李提領處"],"en":["the area where passengers collect their luggage"]}', NULL, 'proceed to baggage claim / baggage claim belt', '[{"en":"Proceed to baggage claim after clearing customs.","zh-TW":"通關後請前往行李提領處。"},{"en":"Her suitcase was the last one on the baggage claim belt.","zh-TW":"她的行李箱是行李輸送帶上最後一件。"}]', NULL, NULL, 5, 536, NULL),
(537, 'bail', '/beɪl/', 'noun', '{"zh-TW":["保釋金"],"en":["money paid to release someone from jail before trial"]}', NULL, 'post bail / bail out', '[{"en":"The judge set bail at $50,000.","zh-TW":"法官將保釋金定為五萬美元。"},{"en":"His family posted bail.","zh-TW":"他的家人交了保釋金。"}]', NULL, NULL, 1, 537, NULL),
(538, 'bailout', '/ˈbeɪlaʊt/', 'noun', '{"zh-TW":["紓困；緊急援助"],"en":["emergency financial assistance given to a failing business or economy"]}', NULL, 'government bailout / bank bailout / financial bailout', '[{"en":"The government approved a bailout package to prevent the bank from collapsing.","zh-TW":"政府批准了一項紓困計畫，以防止銀行崩潰。"},{"en":"Critics argued that bailouts encourage reckless risk-taking by corporations.","zh-TW":"批評者認為，紓困鼓勵了企業不計後果地冒險。"}]', NULL, NULL, 3, 538, NULL),
(539, 'balance', '/ˈbæləns/', 'noun', '{"zh-TW":["平衡；餘額"],"en":["an even distribution of weight","the amount of money remaining in an account"]}', '{"root":{"text":"bi","meaning":"two (二)"},"suffix":{"text":"-lance","meaning":"plate (盤)"},"logic":"兩個盤子的均衡，即「平衡」。"}', 'balance sheet / maintain balance / account balance', '[{"en":"Please check your account balance before making a transfer.","zh-TW":"轉帳前請確認帳戶餘額。"},{"en":"We must maintain a balance between cost and quality.","zh-TW":"我們必須在成本和品質之間保持平衡。"}]', '{"adjective":"balanced"}', NULL, 3, 539, 277),
(540, 'balance brought forward', '/ˈbæləns brɔːt ˈfɔːrwərd/', 'noun', '{"zh-TW":["期初餘額；結轉餘額"],"en":["the balance from a previous period carried into the current accounting period"]}', NULL, 'record balance brought forward / balance brought forward from last month', '[{"en":"The balance brought forward was $15000 from the previous month.","zh-TW":"上月結轉的期初餘額為15,000元。"},{"en":"Balance brought forward ensures continuity between accounting periods.","zh-TW":"結轉餘額確保了會計期間之間的連續性。"}]', NULL, NULL, 5, 540, NULL),
(541, 'balance forward', '/ˈbæləns ˈfɔːrwərd/', 'noun', '{"zh-TW":["結轉餘額"],"en":["an amount carried over to the next accounting period"]}', NULL, 'balance forward from last month / carry a balance forward', '[{"en":"The balance forward from last month was two thousand dollars.","zh-TW":"上個月的結轉餘額為兩千元。"},{"en":"Any unpaid balance will be carried forward to the next statement.","zh-TW":"任何未付餘額將結轉到下一期帳單。"}]', NULL, NULL, 5, 541, NULL),
(542, 'balance of payments', '/ˈbæləns əv ˈpeɪmənts/', 'noun', '{"zh-TW":["國際收支；收支平衡"],"en":["a record of all financial transactions between a country and the rest of the world"]}', NULL, 'monitor the balance of payments / balance of payments deficit', '[{"en":"A persistent balance of payments deficit may weaken the national currency.","zh-TW":"持續的國際收支赤字可能削弱本國貨幣。"},{"en":"The government implemented trade policies to improve the balance of payments.","zh-TW":"政府實施了貿易政策以改善國際收支。"}]', NULL, NULL, 5, 542, NULL),
(543, 'balance of trade', '/ˈbæləns əv treɪd/', 'noun', '{"zh-TW":["貿易差額"],"en":["the difference between a country''s exports and imports"]}', NULL, 'positive balance of trade / balance of trade deficit', '[{"en":"A positive balance of trade means exports exceed imports.","zh-TW":"貿易差額為正表示出口超過進口。"},{"en":"The country worked to improve its negative balance of trade.","zh-TW":"該國努力改善其負貿易差額。"}]', NULL, NULL, 5, 543, NULL),
(544, 'balance sheet', '/ˈbæləns ʃiːt/', 'noun', '{"zh-TW":["資產負債表"],"en":["a financial statement showing assets, liabilities, and equity"]}', NULL, 'review the balance sheet / balance sheet strength / off-balance sheet', '[{"en":"The balance sheet showed total assets of $500 million.","zh-TW":"資產負債表顯示總資產為5億美元。"},{"en":"Investors scrutinize the balance sheet for hidden liabilities.","zh-TW":"投資者仔細審查資產負債表以發現隱藏負債。"}]', NULL, NULL, 5, 544, NULL),
(545, 'balance sheet analysis', '/ˈbæləns ʃiːt əˈnæləsɪs/', 'noun', '{"zh-TW":["資產負債表分析"],"en":["the examination of a company''s balance sheet to assess financial health"]}', NULL, 'conduct balance sheet analysis / balance sheet analysis results', '[{"en":"Balance sheet analysis revealed significant long-term debt accumulation.","zh-TW":"資產負債表分析揭示了顯著的長期債務積累。"},{"en":"Investors use balance sheet analysis to assess solvency and leverage.","zh-TW":"投資者使用資產負債表分析來評估償付能力和槓桿。"}]', NULL, NULL, 5, 545, NULL),
(546, 'balance training', '/''bæləns ˌtreɪnɪŋ/', 'noun', '{"zh-TW":["平衡訓練"],"en":["exercises designed to improve stability, coordination, and body control"]}', NULL, 'include balance training / balance training exercise / benefit of balance training', '[{"en":"Balance training is especially important for older adults to prevent falls.","zh-TW":"平衡訓練對老年人特別重要，可以防止跌倒。"},{"en":"She added balance training to her routine after noticing instability during yoga.","zh-TW":"她在瑜伽期間注意到不穩定後，將平衡訓練加入了她的日常例程。"}]', '{"noun":"balance","adjective":"balanced"}', NULL, 5, 546, NULL),
(547, 'balanced meal', '/''bælənst miːl/', 'noun', '{"zh-TW":["均衡餐食；營養均衡的膳食"],"en":["a meal that contains appropriate proportions of all essential nutrients"]}', NULL, 'prepare a balanced meal / eat a balanced meal / what makes a balanced meal', '[{"en":"A balanced meal should include proteins, carbohydrates, fats, and vegetables.","zh-TW":"均衡餐食應包括蛋白質、碳水化合物、脂肪和蔬菜。"},{"en":"She prepared a balanced meal for the whole family in under thirty minutes.","zh-TW":"她在三十分鐘內為全家準備了一頓均衡的餐食。"}]', NULL, NULL, 5, 547, NULL),
(548, 'balcony', '/ˈbælkəni/', 'noun', '{"zh-TW":["陽台"],"en":["a platform projecting from the wall of a building"]}', NULL, 'balcony room / sea-view balcony', '[{"en":"The suite features a private balcony overlooking the sea.","zh-TW":"套房設有可俯瞰大海的私人陽台。"},{"en":"We enjoyed morning coffee on the balcony.","zh-TW":"我們在陽台享用早晨咖啡。"}]', NULL, NULL, 3, 548, NULL),
(549, 'ball', '/bɔːl/', 'noun', '{"zh-TW":["球；舞會"],"en":["a round object used in games"]}', NULL, 'ball game / have a ball', '[{"en":"Throw the ball to me.","zh-TW":"把球丟給我。"},{"en":"They had a ball at the party.","zh-TW":"他們在派對上玩得很開心。"}]', NULL, NULL, 1, 549, NULL);